"""Repository hygiene (Phase 6): no secrets, no unexpected binaries, no licence chosen on the owner's behalf."""

from __future__ import annotations

import re
import subprocess
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[1]

# binaries we expect and have reviewed: generated by this project (screenshots, the procedural reference GLB) or the
# MIT-licensed three.js bundle. Anything else binary needs a deliberate allow-list entry here (and a licence note).
ALLOWED_BINARY_PREFIXES = ("docs/acceptance/screenshots/", "docs/acceptance/evidence/")
ALLOWED_BINARY_FILES = {"docs/acceptance/ARO-TITAN-480.glb"}
BINARY_EXT = {
    ".png",
    ".jpg",
    ".jpeg",
    ".glb",
    ".gltf",
    ".bin",
    ".zip",
    ".npz",
    ".ckpt",
    ".pt",
    ".pth",
    ".safetensors",
    ".onnx",
    ".fbx",
    ".blend",
    ".obj",
    ".woff",
    ".woff2",
    ".ttf",
    ".ico",
    ".gif",
    ".pdf",
    ".unitypackage",
}
MAX_BYTES = 2_000_000

SECRET_PATTERNS = {
    "hugging face token": r"hf_[A-Za-z0-9]{30,}",
    "github token": r"gh[pousr]_[A-Za-z0-9]{30,}",
    "aws access key": r"AKIA[0-9A-Z]{16}",
    "private key": r"-----BEGIN [A-Z ]*PRIVATE KEY-----",
    "slack token": r"xox[abprs]-[A-Za-z0-9-]{10,}",
    "bearer literal": r"Authorization:\s*Bearer\s+[A-Za-z0-9._-]{24,}",
    "ARO token literal": r"ARO_ACCESS_TOKEN\s*=\s*[A-Za-z0-9_\-]{16,}",
}


def _tracked() -> list[str]:
    try:
        out = subprocess.run(["git", "ls-files"], cwd=ROOT, capture_output=True, text=True, check=True).stdout
    except (OSError, subprocess.CalledProcessError):
        pytest.skip("not a git checkout")
    return [line for line in out.splitlines() if line]


def test_no_secrets_in_tracked_files():
    hits = []
    for f in _tracked():
        p = ROOT / f
        if not p.is_file() or p.suffix.lower() in BINARY_EXT or p.stat().st_size > MAX_BYTES:
            continue
        if f == "tests/test_repository_safety.py":
            continue
        text = p.read_text(errors="ignore")
        for name, rx in SECRET_PATTERNS.items():
            if re.search(rx, text):
                hits.append((f, name))
    assert not hits, f"possible secrets committed: {hits}"


def test_no_unexpected_binary_or_oversized_files():
    bad = []
    for f in _tracked():
        p = ROOT / f
        if not p.is_file():
            continue
        if p.stat().st_size > MAX_BYTES:
            bad.append((f, "larger than 2 MB"))
        if (
            p.suffix.lower() in BINARY_EXT
            and f not in ALLOWED_BINARY_FILES
            and not f.startswith(ALLOWED_BINARY_PREFIXES)
        ):
            bad.append((f, "binary asset not on the reviewed allow-list"))
    assert not bad, f"unreviewed binaries (could be purchased/proprietary assets or model weights): {bad}"


def test_no_model_weights_or_env_files_tracked():
    names = _tracked()
    assert not [
        f for f in names if Path(f).name == ".env" or Path(f).suffix in {".ckpt", ".safetensors", ".pt", ".pth"}
    ]
    assert ".env.example" in names


def test_project_licence_is_still_the_owners_decision():
    """The assistant must not pick the project's software licence. The placeholder stays until the owner decides."""
    text = (ROOT / "LICENSE").read_text()
    assert "PLACEHOLDER" in text and "has not yet chosen a licence" in text
    assert "Permission is hereby granted" not in text and "Apache License" not in text
